"""Payroll summary from multi-site clock exports. Usage: payroll.py INPUT_DIR OUTPUT_FILE"""
import csv
import gzip
import io
import json
import math
import os
import re
import sys
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH_NAIVE = datetime(1970, 1, 1)


# ---------------------------------------------------------------- helpers
def read_text(path):
    with open(path, "rb") as f:
        data = f.read()
    if data[:2] == b"\x1f\x8b":
        data = gzip.decompress(data)
    text = data.decode("utf-8-sig")
    return text


def text_lines(path):
    text = read_text(path)
    return [ln for ln in text.splitlines() if ln.strip() != ""]


def list_files(d):
    out = []
    if not os.path.isdir(d):
        return out
    for root, _dirs, files in os.walk(d):
        for fn in files:
            out.append(os.path.join(root, fn))
    return sorted(out)


def naive_secs(dt):
    """Seconds of a naive datetime counted as if it were UTC."""
    delta = dt - EPOCH_NAIVE
    return delta.days * 86400 + delta.seconds


def local_to_instant(naive, tz, daylight=None):
    """Local wall clock -> UTC epoch seconds.

    daylight: None -> first occurrence of a repeated time; True/False picks the
    daylight / standard occurrence."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    oa, ob = a.utcoffset(), b.utcoffset()
    if oa == ob or oa < ob:  # normal time or a gap
        off = oa
    else:  # repeated time: fold 0 is the daylight occurrence
        if daylight is False:
            off = ob
        else:
            off = oa
    return naive_secs(naive) - int(off.total_seconds())


def utc_offset_at(ts, tz):
    return int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())


def standard_offset(tz, ts):
    dt = datetime.fromtimestamp(ts, tz)
    return int((dt.utcoffset() - (dt.dst() or timedelta(0))).total_seconds())


def parse_iso_offset(s):
    s = s.strip()
    m = re.fullmatch(
        r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:[.,]\d+)?)?\s*(Z|z|[+-]\d\d(?::?\d\d)?)?", s)
    if not m:
        raise ValueError("bad timestamp %r" % s)
    y, mo, d, h, mi, sec, off = m.groups()
    naive = datetime(int(y), int(mo), int(d), int(h), int(mi), int(sec or 0))
    if off is None or off in ("Z", "z"):
        o = 0
    else:
        sign = -1 if off[0] == "-" else 1
        digits = off[1:].replace(":", "")
        oh = int(digits[:2])
        om = int(digits[2:4]) if len(digits) >= 4 else 0
        o = sign * (oh * 3600 + om * 60)
    return naive_secs(naive) - o


def to_int_secs(v):
    return int(math.floor(v))


# ---------------------------------------------------------------- csv with repeated headers
def csv_rows_with_headers(lines, delimiter, is_header):
    """Yield dicts; every header row (as recognised by is_header) replaces the header."""
    header = None
    for row in csv.reader(lines, delimiter=delimiter):
        if not row or all(c.strip() == "" for c in row):
            continue
        cells = [c.strip() for c in row]
        if is_header(cells):
            header = cells
            continue
        if header is None:
            continue
        yield {h: (cells[i] if i < len(cells) else "") for i, h in enumerate(header)}


# ---------------------------------------------------------------- format readers
# every reader returns list of (punch_id, employee, direction 'IN'/'OUT', instant)
def read_abbr_csv(path, tz):
    out = []
    lines = text_lines(path)
    for r in csv_rows_with_headers(lines, ",", lambda c: "Badge" in c and "Punch" in c):
        d = datetime.strptime(r["Date"], "%m/%d/%Y")
        t = r["Time"].strip()
        m = re.fullmatch(r"(\d{1,2}):(\d\d):(\d\d)\s*([AaPp][Mm])?", t)
        if not m:
            raise ValueError("bad time %r" % t)
        h, mi, s, ap = int(m.group(1)), int(m.group(2)), int(m.group(3)), m.group(4)
        if ap:
            ap = ap.upper()
            h = h % 12
            if ap == "PM":
                h += 12
        naive = d.replace(hour=h, minute=mi, second=s)
        z = r.get("Zone", "").strip().upper()
        daylight = None
        if z.endswith("DT"):
            daylight = True
        elif z.endswith("ST"):
            daylight = False
        inst = local_to_instant(naive, tz, daylight)
        direction = r["Punch"].strip().upper()
        out.append((r["Record"].strip(), r["Badge"].strip(), direction, inst))
    return out


def read_epoch_jsonl(path, tz):
    out = []
    schema = 1
    for ln in text_lines(path):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        if not isinstance(o, dict):
            continue
        if "schema" in o and "id" not in o and "punch_id" not in o:
            schema = o["schema"]
            continue
        if o.get("heartbeat"):
            continue
        if schema == 2:
            if "punch_id" not in o:
                continue
            pid, emp, direction = o["punch_id"], o["employee"], o["direction"]
            inst = to_int_secs(o["epoch_ms"] / 1000) if not isinstance(o["epoch_ms"], int) \
                else o["epoch_ms"] // 1000
        else:
            if "id" not in o:
                continue
            pid, emp, direction = o["id"], o["emp"], o["dir"]
            if "ts" in o and o["ts"] is not None:
                inst = to_int_secs(o["ts"])
            else:
                v = o["ts_ms"]
                inst = v // 1000 if isinstance(v, int) else to_int_secs(v / 1000)
        out.append((str(pid).strip(), str(emp).strip(), str(direction).strip().upper(), inst))
    return out


def read_offset_csv(path, tz):
    out = []
    lines = text_lines(path)
    for r in csv_rows_with_headers(lines, ";", lambda c: "punch_id" in c and "event" in c):
        ev = r["event"].strip().lower()
        direction = "IN" if ev == "clock_in" else "OUT"
        out.append((r["punch_id"], r["employee"], direction, parse_iso_offset(r["timestamp"])))
    return out


def read_legacy_fixed(path, tz):
    out = []
    default_off = None
    cur_off = None
    for raw in read_text(path).splitlines():
        ln = raw.rstrip("\r\n")
        if not ln.strip():
            continue
        t = ln[0]
        if t == "H":
            offs = ln[13:18].strip()
            if offs and re.fullmatch(r"[+-]\d{4}", offs):
                sign = -1 if offs[0] == "-" else 1
                cur_off = sign * (int(offs[1:3]) * 3600 + int(offs[3:5]) * 60)
            else:
                cur_off = None
        elif t == "D":
            pid = ln[1:9]
            badge = ln[9:15].strip()
            direction = "IN" if ln[15] == "I" else "OUT"
            dts = ln[16:30]
            naive = datetime.strptime(dts, "%Y%m%d%H%M%S")
            secs = naive_secs(naive)
            if cur_off is not None:
                off = cur_off
            else:
                # standard offset of the site zone (UTC+std all year)
                guess = secs - standard_offset(tz, secs - 0)
                off = standard_offset(tz, guess)
                guess2 = secs - off
                off = standard_offset(tz, guess2)
            out.append((pid, "E" + badge, direction, secs - off))
    return out


def read_de_tsv(path, tz):
    out = []
    lines = text_lines(path)
    for r in csv_rows_with_headers(lines, "\t", lambda c: "Ausweis" in c and "Buchung" in c):
        d = datetime.strptime(r["Datum"], "%d.%m.%Y")
        hh, mm = r["Uhrzeit"].strip().split(":")[:2]
        naive = d.replace(hour=int(hh), minute=int(mm))
        z = r.get("Zeitzone", "").strip().upper()
        daylight = None
        if z == "MESZ":
            daylight = True
        elif z == "MEZ":
            daylight = False
        inst = local_to_instant(naive, tz, daylight)
        b = r["Buchung"].strip().upper()
        direction = "IN" if b == "K" else "OUT"
        out.append((r["Nr"], r["Ausweis"], direction, inst))
    return out


def parse_local(s):
    s = s.strip()
    m = re.fullmatch(r"(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d))?(?:\.\d+)?", s)
    if not m:
        raise ValueError("bad local time %r" % s)
    y, mo, d, h, mi, sec = m.groups()
    return datetime(int(y), int(mo), int(d), int(h), int(mi), int(sec or 0))


def read_local_csv(path, tz):
    out = []
    lines = text_lines(path)
    for r in csv_rows_with_headers(lines, ",", lambda c: "employee_id" in c and "local_time" in c):
        inst = local_to_instant(parse_local(r["local_time"]), tz, None)
        out.append((r["punch_ref"], r["employee_id"], r["direction"].strip().upper(), inst))
    return out


def read_local_jsonl(path, tz):
    out = []
    for ln in text_lines(path):
        try:
            o = json.loads(ln)
        except ValueError:
            continue
        p = o.get("punch") if isinstance(o, dict) else None
        if not isinstance(p, dict):
            continue
        pid = p["id"]
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid).strip()
        inst = local_to_instant(parse_local(p["at"]), tz, None)
        out.append((pid, str(p["badge"]).strip(), str(p["type"]).strip().upper(), inst))
    return out


READERS = {
    "abbr-csv": read_abbr_csv,
    "epoch-jsonl": read_epoch_jsonl,
    "offset-csv": read_offset_csv,
    "legacy-fixed": read_legacy_fixed,
    "de-tsv": read_de_tsv,
    "local-csv": read_local_csv,
    "local-jsonl": read_local_jsonl,
}


# ---------------------------------------------------------------- main computation
def read_csv_file(path):
    return list(csv.DictReader(io.StringIO(read_text(path))))


def main(indir, outfile):
    with open(os.path.join(indir, "period.json")) as f:
        period = json.load(f)
    pstart = date.fromisoformat(period["start"])
    pend = date.fromisoformat(period["end"])
    cutoff = parse_iso_offset(period["corrections_cutoff"])

    sites = {}
    for r in read_csv_file(os.path.join(indir, "sites.csv")):
        sites[r["site"].strip()] = (ZoneInfo(r["timezone"].strip()), r["format"].strip())

    employees = {}
    for r in read_csv_file(os.path.join(indir, "employees.csv")):
        employees[r["employee_id"].strip()] = r["home_site"].strip()

    rates = {}
    for r in read_csv_file(os.path.join(indir, "rates.csv")):
        rates.setdefault(r["employee_id"].strip(), []).append(
            (date.fromisoformat(r["effective_from"].strip()), Decimal(r["hourly_rate"].strip())))
    for v in rates.values():
        v.sort(key=lambda x: x[0])

    # 1. collect
    punches = {}  # (site, id) -> dict(emp, dir, inst)
    existed = set()
    for site in sorted(sites):
        tz, fmt = sites[site]
        reader = READERS[fmt]
        for path in list_files(os.path.join(indir, "exports", site)):
            for pid, emp, direction, inst in reader(path, tz):
                key = (site, pid)
                existed.add(key)
                if key not in punches:
                    punches[key] = {"emp": emp, "dir": direction, "inst": inst}

    # 2. corrections
    corr = []
    for path in list_files(os.path.join(indir, "corrections")):
        try:
            rows = read_csv_file(path)
        except (UnicodeDecodeError, OSError):
            continue
        for r in rows:
            if not r.get("correction_id"):
                continue
            corr.append(r)
    items = []
    for r in corr:
        try:
            issued = parse_iso_offset(r["issued_at"])
        except ValueError:
            continue
        items.append((issued, r["correction_id"], r))
    items.sort(key=lambda x: (x[0], x[1]))
    voided = set()
    applied = 0
    for issued, _cid, r in items:
        if issued > cutoff:
            continue
        action = r["action"].strip().lower()
        key = (r["site"].strip(), r["punch_id"].strip())
        if action == "void":
            if key in punches and key not in voided:
                voided.add(key)
                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches and key not in voided and r.get("time", "").strip():
                punches[key]["inst"] = parse_iso_offset(r["time"])
                applied += 1
        elif action == "add":
            if key not in existed and key[0] in sites:
                typ = r["type"].strip().upper()
                punches[key] = {"emp": r["employee"].strip(), "dir": typ,
                                "inst": parse_iso_offset(r["time"])}
                existed.add(key)
                applied += 1

    by_emp = {}
    for (site, pid), p in punches.items():
        if p["emp"] not in employees:
            continue
        by_emp.setdefault(p["emp"], []).append((p["inst"], 0 if p["dir"] == "OUT" else 1, site, pid, p["dir"]))

    def rounded(inst, site):
        tz = sites[site][0]
        off = utc_offset_at(inst, tz)
        local = inst + off
        r = ((local + 180) // 360) * 360
        return inst + (r - local)

    def workday(rinst, emp):
        hz = sites[employees[emp]][0]
        return datetime.fromtimestamp(rinst, hz).date()

    in_period = lambda d: pstart <= d <= pend
    duplicates = orphans = opens = 0
    results = {e: {"shifts": 0, "paid": 0, "ot": 0, "night": 0, "pay": Fraction(0)} for e in employees}

    def night_minutes(rin, rout, tz):
        total = 0
        d0 = datetime.fromtimestamp(rin, tz).date() - timedelta(days=1)
        d1 = datetime.fromtimestamp(rout, tz).date() + timedelta(days=1)
        d = d0
        while d <= d1:
            nxt = d + timedelta(days=1)
            w0 = local_to_instant(datetime(d.year, d.month, d.day, 22), tz)
            w1 = local_to_instant(datetime(nxt.year, nxt.month, nxt.day, 6), tz)
            lo, hi = max(rin, w0), min(rout, w1)
            if hi > lo:
                total += hi - lo
            d = nxt
        return total // 60

    for emp, plist in by_emp.items():
        plist.sort(key=lambda x: (x[0], x[1], x[2], x[3]))
        kept = []
        last = None
        for inst, _o, site, pid, direction in plist:
            if last is not None and last[4] == direction and inst - last[0] <= 300:
                duplicates_day = workday(rounded(inst, site), emp)
                if in_period(duplicates_day):
                    duplicates += 1
                continue
            last = (inst, _o, site, pid, direction)
            kept.append((rounded(inst, site), site, pid, direction))
        # pair
        shifts = []
        cur = None
        for rinst, site, pid, direction in kept:
            if direction == "IN":
                if cur is not None:
                    if in_period(workday(cur[0], emp)):
                        opens += 1
                cur = (rinst, site)
            else:
                if cur is not None and rinst - cur[0] <= 16 * 3600:
                    shifts.append((cur[0], rinst, cur[1]))
                    cur = None
                else:
                    if cur is not None:
                        if in_period(workday(cur[0], emp)):
                            opens += 1
                        cur = None
                    if in_period(workday(rinst, emp)):
                        orphans += 1
        if cur is not None and in_period(workday(cur[0], emp)):
            opens += 1

        # shift minutes
        rows = []
        for rin, rout, site in shifts:
            wd = workday(rin, emp)
            if not in_period(wd):
                continue
            worked = max(0, (rout - rin) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(rin, rout, sites[site][0]), paid)
            rows.append({"in": rin, "wd": wd, "paid": paid, "night": night, "dot": 0, "wot": 0})
        rows.sort(key=lambda x: x["in"])
        daily = {}
        for r in rows:
            before = daily.get(r["wd"], 0)
            after = before + r["paid"]
            r["dot"] = max(0, after - 480) - max(0, before - 480)
            daily[r["wd"]] = after
        weekly = {}
        for r in rows:
            wk = r["wd"] - timedelta(days=r["wd"].weekday())
            before = weekly.get(wk, 0)
            add = r["paid"] - r["dot"]
            after = before + add
            r["wot"] = max(0, after - 2400) - max(0, before - 2400)
            weekly[wk] = after
        res = results[emp]
        elist = rates.get(emp, [])
        for r in rows:
            ot = r["dot"] + r["wot"]
            reg = r["paid"] - ot
            rate = None
            for eff, val in elist:
                if eff <= r["wd"]:
                    rate = val
            if rate is None:
                rate = elist[0][1] if elist else Decimal(0)
            rate = Fraction(rate)
            res["pay"] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * r["night"] / 60
            res["shifts"] += 1
            res["paid"] += r["paid"]
            res["ot"] += ot
            res["night"] += r["night"]

    def cents(fr):
        c = math.floor(fr * 100 + Fraction(1, 2))
        return c

    out_emps = {}
    tot = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    tot_c = 0
    for emp in sorted(employees):
        r = results[emp]
        c = cents(r["pay"])
        out_emps[emp] = {"shifts": r["shifts"], "paid_minutes": r["paid"], "overtime_minutes": r["ot"],
                         "night_minutes": r["night"], "gross": "%d.%02d" % (c // 100, c % 100)}
        tot["shifts"] += r["shifts"]
        tot["paid_minutes"] += r["paid"]
        tot["overtime_minutes"] += r["ot"]
        tot["night_minutes"] += r["night"]
        tot_c += c
    tot["gross"] = "%d.%02d" % (tot_c // 100, tot_c % 100)
    result = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": out_emps,
        "exceptions": {"open_shifts": opens, "orphan_outs": orphans,
                       "duplicates_dropped": duplicates, "corrections_applied": applied},
        "totals": tot,
    }
    d = os.path.dirname(os.path.abspath(outfile))
    os.makedirs(d, exist_ok=True)
    with open(outfile, "w") as f:
        json.dump(result, f, indent=1)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        sys.exit("usage: payroll.py INPUT_DIR OUTPUT_FILE")
    main(sys.argv[1], sys.argv[2])
